PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS species(dex_no INTEGER PRIMARY KEY,name TEXT NOT NULL,generation INTEGER,region TEXT,primary_type TEXT,secondary_type TEXT,evolution_family TEXT,image_url TEXT,go_available INTEGER DEFAULT 1,notes TEXT);
CREATE TABLE IF NOT EXISTS pokemon(id INTEGER PRIMARY KEY AUTOINCREMENT,dex_no INTEGER NOT NULL REFERENCES species(dex_no),form_key TEXT DEFAULT 'default',nickname TEXT,cp INTEGER,hp INTEGER,gender TEXT,iv_attack INTEGER,iv_defense INTEGER,iv_hp INTEGER,appraisal_stars INTEGER,weight_kg REAL,height_m REAL,shiny INTEGER DEFAULT 0,shadow INTEGER DEFAULT 0,purified INTEGER DEFAULT 0,costume INTEGER DEFAULT 0,favorite INTEGER DEFAULT 0,special_move INTEGER DEFAULT 0,lucky INTEGER DEFAULT 0,caught_date TEXT,fast_move TEXT,charged_move_1 TEXT,charged_move_2 TEXT,next_powerup_stardust INTEGER,next_powerup_candy INTEGER,evolve_candy INTEGER,evolve_item TEXT,second_move_stardust INTEGER,second_move_candy INTEGER,tags TEXT,collector_role TEXT,combat_role TEXT,research_reservation TEXT,action_status TEXT DEFAULT 'KEEP',notes TEXT,verified_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY AUTOINCREMENT,resource_type TEXT NOT NULL,resource_key TEXT NOT NULL,display_name TEXT NOT NULL,quantity INTEGER,seen INTEGER DEFAULT 0,last_updated TEXT,notes TEXT,UNIQUE(resource_type,resource_key));
CREATE TABLE IF NOT EXISTS research(id INTEGER PRIMARY KEY AUTOINCREMENT,research_name TEXT NOT NULL,stage TEXT,task TEXT NOT NULL,progress INTEGER,target INTEGER,status TEXT DEFAULT 'ACTIVE',expires_at TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS action_log(id INTEGER PRIMARY KEY AUTOINCREMENT,occurred_at TEXT DEFAULT CURRENT_TIMESTAMP,action_type TEXT NOT NULL,pokemon_id INTEGER REFERENCES pokemon(id),details TEXT,resource_delta TEXT,source TEXT DEFAULT 'ChatGPT/PMS');
CREATE INDEX IF NOT EXISTS idx_pokemon_dex ON pokemon(dex_no);